describe("sympy/tensor/array/expressions/tests/test_arrayexpr_derivatives.py", () => {
  it("test_arrayexpr_derivatives1:27", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new MatrixSymbol('X', k, k), new MatrixSymbol('X', k, k)))).toBe('PermuteDims(ArrayTensorProduct(I, I), (3)(1 2))');
  });
  it("test_arrayexpr_derivatives1:31", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new ArrayTensorProduct(new MatrixSymbol('A', k, k), new MatrixSymbol('X', k, k), new MatrixSymbol('B', k, k)), new MatrixSymbol('X', k, k)))).toBe('PermuteDims(ArrayTensorProduct(I, I, A, B), (7)(1 2 4)(3 5))');
  });
  it("test_arrayexpr_derivatives1:37", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new ArrayContraction(new MatrixSymbol('X', k, k), [0, 1]), new MatrixSymbol('X', k, k)))).toBe('ArrayContraction(ArrayTensorProduct(I, I), (1, 3))');
  });
  it.fails("test_arrayexpr_derivatives1:41", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new ArrayDiagonal(new MatrixSymbol('X', k, k), [0, 1]), new MatrixSymbol('X', k, k)))).toBe('ArrayDiagonal(ArrayTensorProduct(I, I), (1, 3))');
  });
  it("test_arrayexpr_derivatives1:45", () => {
    const k = new Sym('k');
    expect(sympyStr(dummyEq(new ArrayDiagonal(new ArrayTensorProduct(ElementwiseApplyFunction(Lambda([new Dummy('d', {}, 1000001)], fn('cos', [new Dummy('d', {}, 1000001)])), new MatrixSymbol('X', k, k)), Identity(k), Identity(k)), [0, 3], [1, 5]), new ArrayDiagonal(new ArrayTensorProduct(ElementwiseApplyFunction(Lambda([new Dummy('d', {}, 1000000)], fn('cos', [new Dummy('d', {}, 1000000)])), new MatrixSymbol('X', k, k)), Identity(k), Identity(k)), [0, 3], [1, 5])))).toBe('True');
  });
  it("test_arrayexpr_derivatives1:62", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new ArraySymbol('A', [rational(3), rational(2), k]), new ArraySymbol('A', [rational(3), rational(2), k])))).toBe('PermuteDims(ArrayTensorProduct(I, I, I), (5)(1 2 4 3))');
  });
  it.fails("test_arrayexpr_derivatives1:78", () => {
    const k = new Sym('k');
    expect(sympyStr(arrayDerive(new Reshape(new MatrixSymbol('A', k, k), [new Pow(k, rational(2))]), new MatrixSymbol('A', k, k)))).toBe('Reshape(PermuteDims(ArrayTensorProduct(I, I), (3)(1 2)), (k, k, k**2))');
  });
});

