describe("sympy/tensor/array/expressions/tests/test_convert_array_to_indexed.py", () => {
  it("test_convert_array_to_indexed_main:16", () => {
    const [i, j, k] = symbols('i j k');
    expect(sympyStr(convertArrayToIndexed(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [i, j, k]))).toBe('A[i, j, k]');
  });
  it("test_convert_array_to_indexed_main:20", () => {
    const [i, j, k, l, m, n, o] = symbols('i j k l m n o');
    expect(sympyStr(convertArrayToIndexed(new ArrayTensorProduct(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), new ArraySymbol('B', [rational(3), rational(3)]), new ArraySymbol('C', [rational(3), rational(3)])), [i, j, k, l, m, n, o]))).toBe('A[i, j, k]*B[l, m]*C[n, o]');
  });
  it("test_convert_array_to_indexed_main:21", () => {
    const [i, j, k, l, m, n, o] = symbols('i j k l m n o');
    expect(sympyStr(convertIndexedToArray(new Mul([new ArrayElement(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [i, j, k]), new ArrayElement(new ArraySymbol('B', [rational(3), rational(3)]), [l, m]), new ArrayElement(new ArraySymbol('C', [rational(3), rational(3)]), [n, o])]), [i, j, k, l, m, n, o]))).toBe('ArrayTensorProduct(A, B, C)');
  });
  it("test_convert_array_to_indexed_main:24", () => {
    const i = new Sym('i');
    expect(sympyStr(dummyEq(Sum(new ArrayElement(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [new Dummy('d0', {}, 1000001), i, new Dummy('d0', {}, 1000001)]), [new Dummy('d0', {}, 1000001), rational(0), rational(2)]), Sum(new ArrayElement(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [new Dummy('d_', {}, 1000000), i, new Dummy('d_', {}, 1000000)]), [new Dummy('d_', {}, 1000000), rational(0), rational(2)])))).toBe('True');
  });
  it("test_convert_array_to_indexed_main:27", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(convertArrayToIndexed(new ArrayDiagonal(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [0, 2]), [i, j]))).toBe('A[j, i, j]');
  });
  it("test_convert_array_to_indexed_main:31", () => {
    const [i, j, k] = symbols('i j k');
    expect(sympyStr(convertArrayToIndexed(new PermuteDims(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [1, 2, 0]), [i, j, k]))).toBe('A[k, i, j]');
  });
  it("test_convert_array_to_indexed_main:32", () => {
    const [k, i, j] = symbols('k i j');
    expect(sympyStr(convertIndexedToArray(new ArrayElement(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [k, i, j]), [i, j, k]))).toBe('PermuteDims(A, (0 1 2))');
  });
  it("test_convert_array_to_indexed_main:36", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(convertArrayToIndexed(new ArrayAdd(new ArraySymbol('B', [rational(3), rational(3)]), new ArraySymbol('C', [rational(3), rational(3)]), new PermuteDims(new ArraySymbol('C', [rational(3), rational(3)]), [1, 0])), [i, j]))).toBe('B[i, j] + C[i, j] + C[j, i]');
  });
  it("test_convert_array_to_indexed_main:37", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(convertIndexedToArray(new Add([new ArrayElement(new ArraySymbol('B', [rational(3), rational(3)]), [i, j]), new ArrayElement(new ArraySymbol('C', [rational(3), rational(3)]), [i, j]), new ArrayElement(new ArraySymbol('C', [rational(3), rational(3)]), [j, i])]), [i, j]))).toBe('ArrayAdd(B, C, PermuteDims(C, (0 1)))');
  });
  it("test_convert_array_to_indexed_main:45", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(convertArrayToIndexed(new ZeroArray(rational(3), rational(3)), [i, j]))).toBe('0');
  });
  it("test_convert_array_to_indexed_main:48", () => {
    const i = new Sym('i');
    expect(sympyStr(convertArrayToIndexed(new Reshape(new ArraySymbol('A', [rational(3), rational(3), rational(3)]), [rational(27)]), [i]))).toBe('A[floor(i/9), Mod(floor(i/3), 3), Mod(i, 3)]');
  });
  it("test_convert_array_to_indexed_main:52", () => {
    const i = new Sym('i');
    expect(sympyStr(convertArrayToIndexed(new Reshape(new ArraySymbol('X', [rational(2), rational(3), rational(4), rational(5), rational(6)]), [rational(720)]), [i]))).toBe('X[floor(i/360), Mod(floor(i/120), 3), Mod(floor(i/30), 4), Mod(floor(i/6), 5), Mod(i, 6)]');
  });
  it("test_convert_array_to_indexed_main:57", () => {
    const [i, j, k, l, m] = symbols('i j k l m');
    expect(sympyStr(convertArrayToIndexed(new Reshape(new ArraySymbol('X', [rational(2), rational(3), rational(4), rational(5), rational(6)]), [rational(4), rational(9), rational(2), rational(2), rational(5)]), [i, j, k, l, m]))).toBe('X[floor(i/2 + j/18 + k/36 + l/72 + m/360), Mod(floor(3*i/2 + j/6 + k/12 + l/24 + m/120), 3), Mod(floor(6*i + 2*j/3 + k/3 + l/6 + m/30), 4), Mod(floor(30*i + 10*j/3 + 5*k/3 + 5*l/6 + m/6), 5), Mod(180*i + 20*j + 10*k + 5*l + m, 6)]');
  });
  it("test_convert_array_to_indexed_main:61", () => {
    const [i, j, k] = symbols('i j k');
    expect(sympyStr(convertArrayToIndexed(new Reshape(new ArraySymbol('X', [rational(30)]), [rational(2), rational(3), rational(5)]), [i, j, k]))).toBe('X[15*i + 5*j + k]');
  });
});

