describe("sympy/tensor/array/expressions/tests/test_deprecated_conv_modules.py", () => {
  it("test_deprecated_conv_module_results:19", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(dummyEq(Sum(new Mul([new ArrayElement(new MatrixSymbol('M', rational(3), rational(3)), [i, new Dummy('d0', {}, 1000001)]), new ArrayElement(new MatrixSymbol('N', rational(3), rational(3)), [new Dummy('d0', {}, 1000001), j])]), [new Dummy('d0', {}, 1000001), rational(0), rational(2)]), Sum(new Mul([new ArrayElement(new MatrixSymbol('M', rational(3), rational(3)), [i, new Dummy('d0', {}, 1000000)]), new ArrayElement(new MatrixSymbol('N', rational(3), rational(3)), [new Dummy('d0', {}, 1000000), j])]), [new Dummy('d0', {}, 1000000), rational(0), rational(2)])))).toBe('True');
  });
  it("test_deprecated_conv_module_results:20", () => {
    expect(sympyStr(convertArrayToMatrix(new ArrayContraction(new ArrayTensorProduct(new MatrixSymbol('M', rational(3), rational(3)), new MatrixSymbol('N', rational(3), rational(3))), [1, 2])))).toBe('M*N');
  });
  it("test_deprecated_conv_module_results:21", () => {
    expect(sympyStr(convertMatrixToArray(MatMul(new MatrixSymbol('M', rational(3), rational(3)), new MatrixSymbol('N', rational(3), rational(3)))))).toBe('ArrayContraction(ArrayTensorProduct(M, N), (1, 2))');
  });
  it("test_deprecated_conv_module_results:22", () => {
    const [i, d, j] = symbols('i d j');
    expect(sympyStr(convertIndexedToArray(Sum(new Mul([MatrixElement(new MatrixSymbol('M', rational(3), rational(3)), i, d), MatrixElement(new MatrixSymbol('N', rational(3), rational(3)), d, j)]), [d, rational(0), rational(2)])))).toBe('ArrayContraction(ArrayTensorProduct(M, N), (1, 2))');
  });
});
